func test_grandpa_domestic_apron_is_bounded_off_progression_space() -> void:
	var footprints: Array = _config(VEGETATION_PATH).get("footprints", [])
	var footprint := _entry(footprints, 1001)
	assert_false(footprint.is_empty(),
		"the oversized foreground clump still has no bounded exclusion footprint")
	if footprint.is_empty():
		return
	var centre := Vector2(float(footprint.get("x", 0.0)), float(footprint.get("z", 0.0)))
	var radius := float(footprint.get("radius", 0.0))
	assert_between(radius, 2.8, 3.4,
		"Grandpa's domestic apron is either too small to work or a broad bald clearing")
	assert_true(centre.distance_to(Vector2(-16.7, -21.2)) <= 0.1,
		"Grandpa's apron drifted off the south-east work yard")
	assert_true(centre.distance_to(DOOR) - radius >= 1.8,
		"Grandpa's apron reaches the east-door opening/starter lane")
	for plot_z in [-9.0, -6.6]:
		for plot_x in [-24.4, -22.0, -19.6]:
			assert_true(centre.distance_to(Vector2(plot_x, plot_z)) > radius,
				"Grandpa's apron reaches an interactive farm plot")

func test_grandpa_work_yard_has_one_coherent_domestic_cluster() -> void:
	var cluster := _entry(_config(PROPS_PATH).get("clusters", []), 1035)
	assert_false(cluster.is_empty(), "Grandpa's south-east yard has no domestic work nook")
	if cluster.is_empty():
		return
	var props: Array = cluster.get("props", [])
	assert_eq(props.size(), 4, "Grandpa's work nook should stay compact, not become prop scatter")
	var models: Array[String] = []
	for raw: Variant in props:
		var prop := raw as Dictionary
		models.append(str(prop.get("model", "")))
		var at: Array = prop.get("at", [])
		assert_eq(at.size(), 2, "a Grandpa-yard prop has no world position")
		if at.size() != 2:
			continue
		var point := Vector2(float(at[0]), float(at[1]))
		assert_true(point.y <= -20.4,
			"Grandpa-yard dressing drifted north into the house or door approach")
		assert_true(point.distance_to(DOOR) >= 4.0,
			"Grandpa-yard dressing blocks the opening/starter doorway lane")
	assert_true(models.has("Bench") and models.has("FarmCrate_Apple") and
		models.has("Bucket_Wooden_1") and models.has("Stool"),
		"the domestic harvest/wash/seat hierarchy is incomplete")

func test_bram_faces_the_customer_lane_instead_of_the_stock_wall() -> void:
	var parsed: Variant = JSON.parse_string(FileAccess.get_file_as_string(VILLAGERS_PATH))
	assert_true(parsed is Dictionary, "village NPC data did not parse")
	if not parsed is Dictionary:
		return
	var bram: Dictionary = {}
	for raw: Variant in (parsed as Dictionary).get("villagers", []):
		if raw is Dictionary and str((raw as Dictionary).get("name", "")) == "Bram":
			bram = raw as Dictionary
			break
	assert_false(bram.is_empty(), "Bram is no longer placed in the Inn")
	if bram.is_empty():
		return
	# Pin the production-evidence correction directly. The installed male rig's
	# visible face is local +Z, so Bram's world facing equals the Inn's yaw: the
	# Inn is placed at 90 degrees since OPTION-B (owner 2026-09-29; it was 180
	# on the old north-facing street), which faces him through the bar toward
	# arriving patrons.
	assert_almost_eq(float(bram.get("facing_deg", 0.0)), float(_inn_yaw()), 0.01,
		"Bram no longer uses the production-corrected patron-facing yaw")

func test_final_polish_locations_have_complete_accepted_evidence_rounds() -> void:
	var rounds := {
		"THE-RISE-IDENTITY-R33": "BLIND_REVIEW.md",
		"OLD-QUARRY-TERRACE-R55-DESKTOP-01": "independent-blind-review.md",
		"final-old-mill-63-desktop-01": "BLIND_REVIEW.md",
		"final-warrens-62-desktop-01": "BLIND_REVIEW.md",
	}
	for round_name: String in rounds:
		var root := "res://ralph/reports/MEADOWS-0912/" + round_name
		var manifest_path := root.path_join("manifest.json")
		assert_true(FileAccess.file_exists(manifest_path), "%s has no manifest" % round_name)
		var manifest := _json(manifest_path)
		assert_true(bool(manifest.get("complete", false)), "%s is not complete" % round_name)
		var review_path := root.path_join(str(rounds[round_name]))
		assert_true(FileAccess.file_exists(review_path), "%s has no independent review" % round_name)
		assert_true(FileAccess.get_file_as_string(review_path).contains("PASS"),
			"%s independent review records no PASS" % round_name)

func test_return_targets_match_authored_gates_and_grandpa() -> void:
	var water: Dictionary = JSON.parse_string(FileAccess.get_file_as_string("res://data/config/water_world.json"))
	var stormwood: Dictionary = JSON.parse_string(FileAccess.get_file_as_string("res://data/config/stormwood_world.json"))
	var cloudreach: Dictionary = JSON.parse_string(FileAccess.get_file_as_string("res://data/config/cloudreach_world.json"))
	var destinations := {
		"water": water.entry_anchors.return_to_stormwood.position,
		"stormwood": stormwood.transition_points.cloudreach_return.position,
		"cloudreach": cloudreach.transition_points.meadows_return.position,
	}
	progression.set_flag("water_currents_restored")
	for realm_id: String in destinations:
		log_reader.set_realm(realm_id)
		var at: Array = destinations[realm_id]
		assert_eq(log_reader.tracked_beacon(progression).position, Vector2(at[0], at[2]))
	log_reader.set_realm("meadows")
	var home: Array = _entry("opening_hear_grandpa").beacon.position
	assert_eq(log_reader.tracked_beacon(progression).position, Vector2(home[0], home[1]))

func test_historical_road_baseline_can_only_improve() -> void:
	var result: Dictionary = MODEL.evaluate_all()
	for realm_id: String in HISTORICAL_BASELINE:
		var actual_by_id: Dictionary = {}
		for route: Dictionary in result.get(realm_id, []):
			actual_by_id[str(route.id)] = route
		var expected: Dictionary = HISTORICAL_BASELINE[realm_id]
		assert_eq(actual_by_id.size(), expected.size(),
			"historical route set changed in %s; update ROAD deliberately" % realm_id)
		for route_id: String in expected:
			assert_true(actual_by_id.has(route_id), "%s/%s remains sampled" % [realm_id, route_id])
			if not actual_by_id.has(route_id):
				continue
			var baseline: Array = expected[route_id]
			var actual: Dictionary = actual_by_id[route_id]
			assert_eq(int(actual.samples), int(baseline[0]), "%s/%s sample count" % [realm_id, route_id])
			assert_true(_does_not_regress(actual, baseline),
				"%s/%s may improve but never exceed its measured failure baseline" % [realm_id, route_id])

func test_both_street_legs_place_buildings_and_thresholds_at_their_authored_roles() -> void:
	var inn := _structure("inn")
	var cottage := _structure("cottage_b")
	var workshop := _structure("workshop")
	var shop := _structure("cottage_a")
	assert_eq(inn.get("at", []), [-2.5, -6.0], "OPTION-B: the inn stands west of the green, off the main street")
	assert_eq(float(inn.get("yaw_deg", 0.0)), 90.0, "the inn's public door faces east onto the green")
	assert_eq(cottage.get("at", []), [19.5, -6.0], "the stone cottage stands on the green's east side")
	assert_eq(float(cottage.get("yaw_deg", 0.0)), -90.0, "the cottage door faces west toward the street")
	assert_eq(workshop.get("at", []), [2.0, 12.0], "Tam's workshop stands west of the south leg")
	assert_eq(float(workshop.get("yaw_deg", 0.0)), 90.0, "the workshop bay faces east onto the street")
	assert_eq(shop.get("at", []), [18.0, 4.0], "Mira's shop stands east of the south leg")
	assert_eq(float(shop.get("yaw_deg", 0.0)), -90.0, "Mira's real door faces west onto the street")
	var doorstep_positions: Array[Vector2] = []
	for raw: Variant in (_json(VILLAGE_PATH).get("structures", []) as Array):
		if raw is Dictionary and str((raw as Dictionary).get("prefab", "")) == "doorstep":
			var at: Array = (raw as Dictionary).get("at", []) as Array
			doorstep_positions.append(Vector2(float(at[0]), float(at[1])))
	assert_true(Vector2(3.6, -6.0) in doorstep_positions, "the inn threshold moved with its green-facing door")
	assert_true(Vector2(16.37, -5.0) in doorstep_positions, "the cottage threshold moved with its door")
	assert_true(Vector2(13.87, 5.0) in doorstep_positions, "Mira's threshold moved with the shop door")

func test_every_moved_building_has_scatter_and_ground_cover_exclusion() -> void:
	var clearing := _vegetation_entry("clearings", Vector2(10.0, 8.0))
	assert_true(float(clearing.get("radius", 0.0)) >= 17.0,
		"the south street clears random trees and rocks around its buildings")
	for expected: Dictionary in [
		{"centre": Vector2(-2.5, -6.0), "radius": 7.8},
		{"centre": Vector2(2.0, 12.0), "radius": 7.5},
		{"centre": Vector2(18.0, 4.0), "radius": 6.0},
		{"centre": Vector2(19.5, -6.0), "radius": 5.3},
	]:
		var footprint := _vegetation_entry("footprints", expected.centre)
		assert_true(float(footprint.get("radius", 0.0)) >= float(expected.radius),
			"the moved building at %s rejects even clearing-exempt ground cover" % expected.centre)

func test_fences_define_working_yards_without_cutting_the_street() -> void:
	var fence_poses: Dictionary = {}
	for raw: Variant in (_json(VILLAGE_PATH).get("structures", []) as Array):
		if raw is Dictionary and str((raw as Dictionary).get("prefab", "")) == "fence_run":
			fence_poses[_at(raw as Dictionary)] = float((raw as Dictionary).get("yaw_deg", INF))
	assert_eq(fence_poses.get(Vector2(28.0, 4.0), INF), 90.0,
		"Oskar's pen has a rear rail parallel to the shop wall")
	assert_eq(fence_poses.get(Vector2(-10.0, 15.0), INF), 90.0,
		"Tam's rear yard has a west rail")
	assert_eq(fence_poses.get(Vector2(-7.0, 18.0), INF), 0.0,
		"Tam's rear rails meet as a readable L")
	assert_false(fence_poses.has(Vector2(-11.0, -9.5)),
		"the orphaned yard rail no longer cuts across the inn/Grandpa street composition")
	for at: Vector2 in [Vector2(28.0, 4.0), Vector2(-10.0, 15.0), Vector2(-7.0, 18.0)]:
		assert_true(at.distance_to(Vector2(12.0, at.y)) >= 11.0,
			"yard rail at %s remains outside the south-street walking lane" % at)

func test_opening_village_keeps_exactly_five_functional_people_inside() -> void:
	var outline := BOUNDARY.outline(BOUNDARY.load_config())
	var inside: Array[String] = []
	for raw: Variant in _people():
		var spec := raw as Dictionary
		if BOUNDARY.contains(outline, _point(spec)):
			inside.append(str(spec.get("name", "")))
	inside.sort()
	var expected: Array[String] = []
	for name: String in OPENING_FIVE:
		expected.append(name)
	expected.sort()
	assert_eq(inside, expected,
		"the village boundary contains exactly its five opening functions, not an idle crowd")

func test_south_street_has_one_continuous_hidden_road_to_trailgate() -> void:
	var paths := _json(TERRAIN_PATH).get("paths", {}) as Dictionary
	var street: Dictionary = {}
	for raw: Variant in (paths.get("approaches", []) as Array):
		if raw is Dictionary and str((raw as Dictionary).get("id", "")) == "village_south_street":
			street = raw as Dictionary
	assert_false(street.is_empty(), "the well-to-TrailGate street is authored as painted ground")
	assert_eq(street.get("points", []), [[10.5, 2.0], [11.5, 2.0], [14.0, 20.0]],
		"the south street leaves the main street at z=2 and meets the existing TrailGate waypoint")
	var grandpa_route: Dictionary = {}
	var inn_route: Dictionary = {}
	for raw: Variant in (paths.get("routes", []) as Array):
		if raw is Dictionary and str((raw as Dictionary).get("label", "")) == "Grandpa's House":
			grandpa_route = raw as Dictionary
		if raw is Dictionary and str((raw as Dictionary).get("label", "")) == "The Inn":
			inn_route = raw as Dictionary
	assert_false(grandpa_route.is_empty(), "the west street to Grandpa remains authored")
	assert_eq(grandpa_route.get("points", []), [[10.5, -16.0], [-16.5, -16.0]],
		"the cross lane runs straight along z=-16 from the main street to Grandpa's real door")
	# OPTION-B: the inn's path leaves the main street at the green's north edge
	# and ends on the doorstep that faces the green.
	assert_eq(inn_route.get("points", []), [[10.5, -10.0], [6.6, -7.0], [3.6, -6.0]],
		"the inn has a short path from the main street to its green-facing doorstep")
	assert_true(Vector2(10.5, -10.0).distance_to(Vector2(10.5, -6.0)) >= 4.0,
		"the inn path leaves the street at the green's edge, clear of the well canopy and bucket")

func test_farm_json_places_beds_where_r7_6_allows() -> void:
	var config := _json(FARM_CONFIG)
	var plots: Array = config.get("plots", [])
	assert_true(plots.size() > 0, "farm.json places no beds at all")
	assert_true(int(config.get("grow_days", 0)) >= 1, "grow_days must be at least a day")
	assert_true(int(config.get("yield", 0)) >= 1, "a bed that yields nothing is not a farm")
	assert_true(db.has(str(config.get("seed_item", ""))), "farm.json names an unknown seed item")
	assert_true(db.has(str(config.get("crop_item", ""))), "farm.json names an unknown crop item")

	# R7.6's stated constraints: beside Grandpa's house at [-22,-16], clear of
	# the square flat at [10,-10] r18 and of the fence run at [3,-18]. Also
	# inside the house pad's own full-flatten radius (r14), or a bed stands on
	# the skirt and tilts.
	var house := Vector2(-22.0, -16.0)
	var square := Vector2(10.0, -10.0)
	var fence := Vector2(3.0, -18.0)
	for entry: Variant in plots:
		var at: Array = (entry as Dictionary).get("at", [])
		assert_eq(at.size(), 2, "a farm plot has no [x, z]")
		var here := Vector2(float(at[0]), float(at[1]))
		assert_true(here.distance_to(house) <= 14.0,
			"bed at %s is outside the house pad's flatten radius" % str(here))
		assert_true(here.distance_to(square) > 18.0,
			"bed at %s intrudes on the square flat" % str(here))
		assert_true(here.distance_to(fence) > 4.0,
			"bed at %s sits on the fence run" % str(here))


