func test_authored_route_survives_coarse_terrain_sampling() -> void:
	var image := MAP_BAKER.bake(FakeWorld.new(), RESOLUTION, TEST_BOUNDS).get_image()
	# Grandpa's House route starts at the square bend (7,-7) (F01-a moved every
	# route origin off the well at (10,-10)). At this deliberately coarse
	# 8m/px bake its 3m width cannot reliably hit texel centres, so this point
	# specifically proves the canonical-polyline overlay carries the route.
	var route_pixel := _world_to_pixel(Vector2(7.0, -7.0))
	# RGB8 quantizes the authored float colour on write.
	var actual := image.get_pixelv(route_pixel)
	assert_true(maxf(absf(actual.r - MAP_BAKER.PATH_COLOUR.r),
		maxf(absf(actual.g - MAP_BAKER.PATH_COLOUR.g), absf(actual.b - MAP_BAKER.PATH_COLOUR.b))) < 0.01,
		"an authored route waypoint must remain visible at minimap bake density")

func test_exact_failed_baked_tree_spawns_reachable_prompt_without_radius_change() -> void:
	var placement := _exact_placement()
	assert_false(placement.is_empty())
	assert_eq(placement.harvest_layer, "trees")
	assert_eq(placement.harvest_index, 320)
	var vegetation := VEG.new()
	vegetation._mesh_ids[str(placement.model)] = 0
	vegetation._spawn_harvest_point(placement)
	var point: Node3D = vegetation._harvest_nodes["trees#320"]
	var prompt: Node3D = point.get_node("Interactable")
	assert_almost_eq(float(prompt.radius), 2.6, 0.00001)
	assert_eq(point.resource_item(), "wood")
	assert_eq(point.resource_amount(), 2)
	# Actual grounded contact measured by the native production-collider probe.
	var contact := Vector3(45.45166, -0.465704, -61.39447)
	var old := Vector3(placement.position) + Vector3.UP * (1.0 + float(placement.scale))
	var current := Vector3(placement.position) + prompt.position
	assert_true(contact.distance_to(old) > float(prompt.radius))
	assert_true(contact.distance_to(current) < float(prompt.radius))
	vegetation.free()

func test_bake_manifest_is_fresh_and_covers_routes_and_surface() -> void:
	var manifest := _json("%s/manifest.json" % DATA_DIR)
	assert_eq(int(manifest.regions), 108, "a full-world bake")
	var hashes: Dictionary = manifest.dependency_hashes
	for path: String in [BAKER.WORLD_PATH, BAKER.SURFACE_PATH, BAKER.TEXTURES_PATH, BAKER.SCRIPT_PATH]:
		assert_true(hashes.has(path), "the fingerprint covers %s" % path)
	assert_eq(int(manifest.dependency_fingerprint), BAKER.current_fingerprint(), "the committed bake is fresh for this checkout")
	# Negative control: moving one spur point by 1 m stales the fingerprint.
	var sources := {}
	for path: String in BAKER.dependency_paths():
		sources[path] = FileAccess.get_file_as_string(path)
	var world_text := str(sources[BAKER.WORLD_PATH])
	var moved := world_text.replace("[-335.0,369.2]", "[-336.0,369.2]")
	assert_ne(moved, world_text, "control setup: the spur point is in the file")
	sources[BAKER.WORLD_PATH] = moved
	assert_ne(BAKER.dependency_fingerprint(sources), int(manifest.dependency_fingerprint), "control: a moved route stales the bake")
